#!/usr/bin/env node

/**
 * Security Audit Script for Express Application
 * Checks for common security vulnerabilities and misconfigurations
 */

const fs = require('fs');
const path = require('path');
const { execSync, spawn } = require('child_process');

console.log('🔒 SECURITY AUDIT STARTED');
console.log('='.repeat(50));

const issues = [];
const warnings = [];
const recommendations = [];

// Color codes for console output
const colors = {
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
  reset: '\x1b[0m'
};

function logIssue(severity, message, fix = '') {
  const color = severity === 'CRITICAL' ? colors.red : 
                severity === 'HIGH' ? colors.yellow : 
                severity === 'MEDIUM' ? colors.blue : colors.cyan;

  console.log(`${color}[${severity}]${colors.reset} ${message}`);
  if (fix) {
    console.log(`   ${colors.green}Fix:${colors.reset} ${fix}`);
  }
  console.log();

  issues.push({ severity, message, fix });
}

function logWarning(message) {
  console.log(`${colors.yellow}[WARNING]${colors.reset} ${message}`);
  warnings.push(message);
  console.log();
}

function logRecommendation(message) {
  console.log(`${colors.cyan}[RECOMMENDATION]${colors.reset} ${message}`);
  recommendations.push(message);
  console.log();
}

// ===== CHECK 1: Environment Variables =====
console.log(`${colors.magenta}1. Checking Environment Variables${colors.reset}`);

const envFiles = [
  '.env',
  '.env.local',
  '.env.development',
  '.env.production',
  '.env.test'
];

envFiles.forEach(file => {
  if (fs.existsSync(file)) {
    const content = fs.readFileSync(file, 'utf8');

    // Check for hardcoded secrets
    const secretPatterns = [
      /password\s*=/i,
      /secret\s*=/i,
      /key\s*=/i,
      /token\s*=/i,
      /CANARY/i,
      /aws_access_key_id/i,
      /aws_secret_access_key/i,
      /api_key/i,
      /database_url/i,
      /stripe/i,
      /private/i
    ];

    secretPatterns.forEach(pattern => {
      if (pattern.test(content)) {
        const lines = content.split('\n');
        lines.forEach((line, index) => {
          if (pattern.test(line)) {
            logIssue('CRITICAL', 
              `Hardcoded secret found in ${file}:${index + 1}`, 
              `Remove "${line.trim()}" from file and use environment variables`
            );
          }
        });
      }
    });

    // Check for .env.test specifically
    if (file === '.env.test' && fs.existsSync('.env.test')) {
      logIssue('CRITICAL',
        '.env.test file found with production-like secrets',
        'Delete .env.test and ensure .env* files are in .gitignore'
      );
    }
  }
});

// Check if .gitignore includes .env files
if (fs.existsSync('.gitignore')) {
  const gitignore = fs.readFileSync('.gitignore', 'utf8');
  if (!gitignore.includes('.env') && !gitignore.includes('.env*')) {
    logIssue('HIGH',
      '.gitignore does not exclude environment files',
      'Add ".env\n.env.*\n!.env.example" to .gitignore'
    );
  }
}

// ===== CHECK 2: Dependencies =====
console.log(`${colors.magenta}2. Checking Dependencies${colors.reset}`);

if (fs.existsSync('package.json')) {
  try {
    const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));

    // Check for security-related dependencies
    const securityDeps = ['helmet', 'express-validator', 'express-rate-limit', 'jsonwebtoken', 'bcrypt', 'cors'];
    const missingDeps = securityDeps.filter(dep => 
      !packageJson.dependencies?.[dep] && !packageJson.devDependencies?.[dep]
    );

    if (missingDeps.length > 0) {
      logIssue('HIGH',
        `Missing security dependencies: ${missingDeps.join(', ')}`,
        `Run: npm install ${missingDeps.join(' ')}`
      );
    }

    // Check npm audit
    try {
      console.log('   Running npm audit...');
      const auditResult = execSync('npm audit --json', { encoding: 'utf8', stdio: 'pipe' });
      const audit = JSON.parse(auditResult);

      if (audit.metadata && audit.metadata.vulnerabilities) {
        const vulns = audit.metadata.vulnerabilities;
        Object.keys(vulns).forEach(severity => {
          const count = vulns[severity];
          if (count > 0) {
            logIssue(severity.toUpperCase(),
              `${count} ${severity} severity vulnerabilities found in dependencies`,
              'Run: npm audit fix'
            );
          }
        });
      }
    } catch (error) {
      logWarning('npm audit failed or no package-lock.json found');
    }

  } catch (error) {
    logWarning('Failed to parse package.json');
  }
} else {
  logIssue('MEDIUM',
    'No package.json found',
    'Create package.json with dependency management'
  );
}

// ===== CHECK 3: Application Code =====
console.log(`${colors.magenta}3. Checking Application Code${colors.reset}`);

const jsFiles = [];
function findJSFiles(dir) {
  const files = fs.readdirSync(dir);
  files.forEach(file => {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);
    if (stat.isDirectory() && file !== 'node_modules') {
      findJSFiles(filePath);
    } else if (file.endsWith('.js')) {
      jsFiles.push(filePath);
    }
  });
}

try {
  findJSFiles('.');
} catch (error) {
  // If can't read directory, just check current directory
  const files = fs.readdirSync('.');
  files.forEach(file => {
    if (file.endsWith('.js')) {
      jsFiles.push(file);
    }
  });
}

jsFiles.forEach(file => {
  try {
    const content = fs.readFileSync(file, 'utf8');

    // Check for common vulnerabilities
    const checks = [
      {
        pattern: /eval\s*\(/,
        message: `eval() found in ${file}`,
        severity: 'CRITICAL',
        fix: 'Remove eval() - use JSON.parse() or Function constructor with caution'
      },
      {
        pattern: /child_process\.exec\s*\(/,
        message: `child_process.exec() found in ${file}`,
        severity: 'CRITICAL',
        fix: 'Use child_process.execFile() or spawn() with explicit arguments'
      },
      {
        pattern: /fs\.readFileSync.*\+\s*req\./,
        message: `Potential path traversal in ${file}`,
        severity: 'HIGH',
        fix: 'Validate and sanitize file paths before reading'
      },
      {
        pattern: /console\.log.*password|secret|token/i,
        message: `Sensitive data logging in ${file}`,
        severity: 'HIGH',
        fix: 'Remove sensitive data from console logs'
      },
      {
        pattern: /res\.send.*stack/i,
        message: `Stack trace exposure in ${file}`,
        severity: 'MEDIUM',
        fix: 'Hide stack traces in production: process.env.NODE_ENV === "production"'
      },
      {
        pattern: /app\.get.*users.*requireAuth/,
        message: `Authentication check found in ${file}`,
        severity: 'INFO',
        fix: 'Good practice: Endpoints are protected'
      },
      {
        pattern: /rateLimit|ratelimiter/i,
        message: `Rate limiting found in ${file}`,
        severity: 'INFO',
        fix: 'Good practice: Rate limiting implemented'
      }
    ];

    checks.forEach(check => {
      if (check.pattern.test(content)) {
        if (check.severity === 'INFO') {
          console.log(`${colors.green}[GOOD PRACTICE]${colors.reset} ${check.message}`);
        } else {
          logIssue(check.severity, check.message, check.fix);
        }
      }
    });

    // Check for missing security middleware
    if (file.includes('app') && !content.includes('helmet') && !content.includes('X-Content-Type-Options')) {
      logRecommendation(`Add security headers middleware in ${file}`);
    }

    if (file.includes('app') && !content.includes('express-validator') && !content.includes('validationResult')) {
      logRecommendation(`Add input validation in ${file}`);
    }

  } catch (error) {
    logWarning(`Could not read file ${file}: ${error.message}`);
  }
});

// ===== CHECK 4: File System Permissions =====
console.log(`${colors.magenta}4. Checking File Permissions${colors.reset}`);

// Check for world-writable files
try {
  const files = fs.readdirSync('.');
  files.forEach(file => {
    try {
      const stats = fs.statSync(file);
      // Check if file is writable by others (not perfect, but indicative)
      if (stats.mode & 0o002) {
        if (file.includes('.js') || file.includes('.env')) {
          logIssue('HIGH',
            `World-writable file: ${file}`,
            `Run: chmod o-w ${file}`
          );
        }
      }
    } catch (e) {
      // Ignore permission errors
    }
  });
} catch (error) {
  logWarning('Could not check file permissions');
}

// ===== SUMMARY =====
console.log(`${colors.magenta}SECURITY AUDIT SUMMARY${colors.reset}`);
console.log('='.repeat(50));

const criticalCount = issues.filter(i => i.severity === 'CRITICAL').length;
const highCount = issues.filter(i => i.severity === 'HIGH').length;
