/**
 * Secure Secrets Loader
 * 
 * Handles loading secrets securely in different environments:
 * - Production: AWS Secrets Manager, environment variables
 * - Development: .env file with warnings
 * - Testing: Mock/test values
 */

const fs = require('fs');
const path = require('path');

class SecretsLoader {
  constructor() {
    this.secrets = {};
    this.isProduction = process.env.NODE_ENV === 'production';
    this.isDevelopment = process.env.NODE_ENV === 'development' || !process.env.NODE_ENV;
    this.isTest = process.env.NODE_ENV === 'test';

    this.requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'SESSION_SECRET'
    ];

    this.optionalSecrets = [
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN'
    ];
  }

  async load() {
    console.log(`🔐 Loading secrets for ${process.env.NODE_ENV || 'development'} environment`);

    try {
      if (this.isProduction) {
        await this.loadProductionSecrets();
      } else if (this.isDevelopment) {
        await this.loadDevelopmentSecrets();
      } else if (this.isTest) {
        await this.loadTestSecrets();
      }

      this.validateSecrets();
      this.setProcessEnv();
      this.logSecurityStatus();

      return this.secrets;
    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);
      process.exit(1);
    }
  }

  async loadProductionSecrets() {
    console.log('🌐 Production environment detected');

    // Method 1: Check for AWS Secrets Manager
    if (process.env.AWS_SECRETS_MANAGER_SECRET_ID) {
      console.log('   Using AWS Secrets Manager');
      await this.loadFromAWSSecretsManager();
      return;
    }

    // Method 2: Check for environment variables (e.g., from ECS, EKS, Lambda)
    console.log('   Checking environment variables...');
    const fromEnv = this.loadFromEnvironment();

    if (this.hasRequiredSecrets(fromEnv)) {
      this.secrets = fromEnv;
      console.log('   ✅ Secrets loaded from environment variables');
      return;
    }

    // Method 3: Check for mounted secrets (e.g., Docker/K8s secrets)
    console.log('   Checking mounted secret files...');
    const fromFiles = await this.loadFromMountedFiles();

    if (this.hasRequiredSecrets(fromFiles)) {
      this.secrets = fromFiles;
      console.log('   ✅ Secrets loaded from mounted files');
      return;
    }

    throw new Error('No valid secrets source found for production');
  }

  async loadFromAWSSecretsManager() {
    try {
      // AWS SDK will use IAM role credentials in production
      const AWS = require('aws-sdk');
      const client = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const data = await client.getSecretValue({
        SecretId: process.env.AWS_SECRETS_MANAGER_SECRET_ID
      }).promise();

      let secretString;
      if (data.SecretString) {
        secretString = data.SecretString;
      } else {
        secretString = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      this.secrets = JSON.parse(secretString);
      console.log('   ✅ Secrets retrieved from AWS Secrets Manager');
    } catch (error) {
      console.error('   ❌ Failed to load from AWS Secrets Manager:', error.message);
      throw error;
    }
  }

  loadFromEnvironment() {
    const secrets = {};

    [...this.requiredSecrets, ...this.optionalSecrets].forEach(key => {
      if (process.env[key]) {
        secrets[key] = process.env[key];
      }
    });

    return secrets;
  }

  async loadFromMountedFiles() {
    const secrets = {};
    const basePath = process.env.SECRETS_PATH || '/run/secrets';

    if (!fs.existsSync(basePath)) {
      return secrets;
    }

    try {
      const secretFiles = fs.readdirSync(basePath);

      for (const file of secretFiles) {
        const secretPath = path.join(basePath, file);
        try {
          const content = fs.readFileSync(secretPath, 'utf8').trim();
          secrets[file] = content;
        } catch (error) {
          console.warn(`   ⚠️  Could not read secret file ${file}:`, error.message);
        }
      }
    } catch (error) {
      console.warn('   ⚠️  Could not read secrets directory:', error.message);
    }

    return secrets;
  }

  async loadDevelopmentSecrets() {
    console.log('💻 Development environment detected');

    // Always warn about .env files in development
    console.warn('   ⚠️  WARNING: Using .env files for secrets (development only)');
    console.warn('   For production, use a secrets manager like AWS Secrets Manager');

    const envPath = path.join(process.cwd(), '.env');

    if (!fs.existsSync(envPath)) {
      // Create example file if missing
      this.createExampleEnvFile(envPath);
      console.error(`   ❌ No .env file found at ${envPath}`);
      console.error(`   ℹ️  Created .env.example for reference`);
      process.exit(1);
    }

    // Load with dotenv
    require('dotenv').config({ path: envPath });

    // Load secrets from process.env
    this.secrets = this.loadFromEnvironment();

    // Special validation for development
    this.validateDevelopmentSecrets();

    console.log('   ✅ Development secrets loaded');
  }

  async loadTestSecrets() {
    console.log('🧪 Test environment detected');

    // For tests, use mock values
    this.secrets = {
      DATABASE_URL: 'postgres://test:test@localhost:5432/testdb',
      JWT_SECRET: 'test-jwt-secret-123',
      SESSION_SECRET: 'test-session-secret-456'
    };

    // Add optional mock values
    this.optionalSecrets.forEach(key => {
      this.secrets[key] = `mock-${key.toLowerCase().replace(/_/g, '-')}`;
    });

    console.log('   ✅ Test secrets loaded (mock values)');
  }

  validateSecrets() {
    const missing = this.requiredSecrets.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Validate secret formats
    this.validateSecretFormats();
  }

  validateSecretFormats() {
    const validations = [
      {
        key: 'DATABASE_URL',
        pattern: /^(postgres|mongodb|mysql):\/\//,
        message: 'DATABASE_URL should start with postgres://, mongodb://, or mysql://'
      },
      {
        key: 'JWT_SECRET',
        minLength: 32,
        message: 'JWT_SECRET should be at least 32 characters'
      },
      {
        key: 'AWS_ACCESS_KEY_ID',
        pattern: /^AKIA[0-9A-Z]{16}$/,
        optional: true,
        message: 'AWS_ACCESS_KEY_ID should match AKIA-xxxxxxxxxxxxxxxx'
      }
    ];

    validations.forEach(({ key, pattern, minLength, optional, message }) => {
      const value = this.secrets[key];

      if (!value && optional) return;

      if (value) {
        if (pattern && !pattern.test(value)) {
          console.warn(`   ⚠️  ${key} format warning: ${message}`);
        }
        if (minLength && value.length < minLength) {
          console.warn(`   ⚠️  ${key} is too short (${value.length} chars), minimum ${minLength}`);
        }
      }
    });
  }

  validateDevelopmentSecrets() {
    console.log('   🔍 Validating development secrets...');

    const dangerPatterns = [
      {
        pattern: /production/i,
        message: 'Contains "production" - are you sure this is for development?'
      },
      {
        pattern: /live_/i,
        message: 'Contains "live_" prefix - is this a production key?'
      },
      {
        pattern: /CANARY/i,
        message: 'Contains "CANARY" - this looks like a honeypot value'
      },
      {
        pattern: /real_|prod_/i,
        message: 'Contains production indicator - verify this is for development'
      }
    ];

    let warnings = 0;

    for (const [key, value] of Object.entries(this.secrets)) {
      dangerPatterns.forEach(({ pattern, message }) => {
        if (pattern.test(value)) {
          console.warn(`     ⚠️  ${key}: ${message}`);
          warnings++;
        }
      });

      // Check for extremely weak secrets
      if (key.includes('SECRET') || key.includes('PASSWORD')) {
        if (value.length < 8) {
          console.warn(`     ⚠️  ${key} is very short (${value.length} chars)`);
          warnings++;
        }
        if (value === 'password' || value === 'secret' || value === '123456') {
          console.warn(`     ⚠️  ${key} uses a common/default password`);
          warnings++;
        }
      }
    }

    if (warnings > 0) {
      console.warn(`   Found ${warnings} security warning(s) in development secrets`);
    } else {
      console.log('   ✅ Development secrets validation passed');
    }
  }

  createExampleEnvFile(envPath) {
    const examplePath = envPath + '.example';
    const exampleContent = `# Environment Configuration
# Copy this file to .env and fill in your values
# NEVER commit .env to version control!

# Database
DATABASE_URL=postgres://username:password@localhost:5432/dbname

# Security
JWT_SECRET=your-super-secure-jwt-secret-minimum-32-characters-here
SESSION_SECRET=another-secure-session-secret-minimum-32-characters

# API Keys (optional, only if needed)
# AWS_ACCESS_KEY_ID=AKIA-XXXXXXXXXXXXXXXX
# AWS_SECRET_ACCESS_KEY=your-aws-secret-key
# STRIPE_SECRET_KEY=sk-test-your_stripe_key
# ANTHROPIC_API_KEY=sk-ant-your-api-key

# Server
PORT=3000
NODE_ENV=development

# Logging
LOG_LEVEL=info

# CORS (development)
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:8080
`;

    fs.writeFileSync(examplePath, exampleContent);
  }

  hasRequiredSecrets(secrets) {
    return this.requiredSecrets.every(key => secrets[key]);
  }

  setProcessEnv() {
    // Merge loaded secrets into process.env
    Object.assign(process.env, this.secrets);
  }

  logSecurityStatus() {
    console.log('🔒 Security Status:');

    if (this.isProduction) {
      console.log('   ✅ Production: Using secure secrets source');

      if (process.env.AWS_SECRETS_MANAGER_SECRET_ID) {
        console.log('   ✅ AWS Secrets Manager integration active');
      }

      if (process.env.AWS_REGION) {
        console.log('   ✅ AWS region configured');
      }

      // Check for IAM role usage (preferred over keys)
      if (!this.secrets.AWS_ACCESS_KEY_ID && !this.secrets.AWS_SECRET_ACCESS_KEY) {
        console.log('   ✅ Using IAM roles for AWS access (recommended)');
      } else {
        console.warn('   ⚠️  Using AWS keys directly (consider IAM roles)');
      }
    } else {
      console.log('   🔶 Development: .env file loaded with warnings');
