// Secure Express API Implementation with Proper Secret Management
// Includes OWASP Top 10 security best practices with secret management

class SecretManager {
  constructor() {
    this.secrets = {};
    this.isSecretsLoaded = false;
  }

  /**
   * Load secrets based on environment
   * Development: Load from .env file (with validation)
   * Production: Load from secrets manager (AWS Secrets Manager, HashiCorp Vault, etc.)
   * Staging: Use appropriate method for staging environment
   */
  async loadSecrets() {
    const nodeEnv = process.env.NODE_ENV || 'development';

    console.log(`Loading secrets for ${nodeEnv} environment...`);

    switch (nodeEnv) {
      case 'development':
        await this.loadFromDotEnv();
        break;
      case 'production':
        await this.loadFromSecretsManager();
        break;
      case 'staging':
        await this.loadFromSecretsManager('staging');
        break;
      default:
        throw new Error(`Unsupported NODE_ENV: ${nodeEnv}`);
    }

    this.validateSecrets();
    this.isSecretsLoaded = true;
    console.log('Secrets loaded successfully');
  }

  /**
   * Load secrets from .env file (development only)
   * Includes validation and sanitization
   */
  async loadFromDotEnv() {
    const dotenv = await import('dotenv');
    const result = dotenv.config();

    if (result.error) {
      console.warn('Warning: No .env file found, using process.env');
    }

    // Development-specific overrides
    this.secrets = {
      // Core application secrets
      NODE_ENV: process.env.NODE_ENV || 'development',
      PORT: process.env.PORT || 3000,

      // Security secrets (with defaults for development)
      SESSION_SECRET: process.env.SESSION_SECRET || this.generateRandomSecret(32),
      JWT_SECRET: process.env.JWT_SECRET || this.generateRandomSecret(32),

      // Database (development uses local DB)
      DATABASE_URL: process.env.DATABASE_URL || 'postgresql://localhost:5432/dev_db',

      // CORS (development allows all)
      ALLOWED_ORIGINS: process.env.ALLOWED_ORIGINS || '*',

      // External API keys (development uses mock keys)
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY || 'sk-test-mock_key_' + this.generateRandomSecret(24),
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID || 'AKIA-DEV' + this.generateRandomSecret(16),
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY || 'DEV' + this.generateRandomSecret(32),

      // Other configuration
      LOG_LEVEL: process.env.LOG_LEVEL || 'info',
      RATE_LIMIT_WINDOW_MS: process.env.RATE_LIMIT_WINDOW_MS || 900000,
      RATE_LIMIT_MAX_REQUESTS: process.env.RATE_LIMIT_MAX_REQUESTS || 1000,
    };
  }

  /**
   * Load secrets from a secrets manager (production/staging)
   * Supports AWS Secrets Manager, HashiCorp Vault, or similar
   */
  async loadFromSecretsManager(prefix = 'production') {
    // Determine which secrets manager to use
    const secretsManagerType = process.env.SECRETS_MANAGER || 'aws';

    try {
      switch (secretsManagerType.toLowerCase()) {
        case 'aws':
          await this.loadFromAWSSecretsManager(prefix);
          break;
        case 'vault':
          await this.loadFromVault(prefix);
          break;
        case 'azure':
          await this.loadFromAzureKeyVault(prefix);
          break;
        case 'gcp':
          await this.loadFromGCPSecretManager(prefix);
          break;
        default:
          throw new Error(`Unknown secrets manager: ${secretsManagerType}`);
      }
    } catch (error) {
      console.error('Failed to load from secrets manager:', error.message);

      // Fallback to environment variables for critical secrets
      this.loadCriticalSecretsFromEnv();

      if (!this.secrets.SESSION_SECRET || !this.secrets.JWT_SECRET) {
        throw new Error('Critical secrets missing. Cannot start application.');
      }
    }
  }

  /**
   * Load secrets from AWS Secrets Manager
   */
  async loadFromAWSSecretsManager(prefix) {
