   * Validate that a secret meets minimum strength requirements
   */
  validateSecretStrength(secretName, minLength) {
    const secret = this.secrets[secretName];

    if (secret && secret.length < minLength) {
      console.warn(`Warning: ${secretName} is shorter than recommended minimum of ${minLength} characters`);
    }

    // Check for common weak patterns
    if (secret && (
      secret.includes('secret') ||
      secret.includes('password') ||
      secret.includes('123456') ||
      secret === 'changeme'
    )) {
      console.warn(`Warning: ${secretName} contains weak patterns`);
    }
  }

