  /**
   * Get a secret value
   */
  get(key) {
    if (!this.isSecretsLoaded) {
      throw new Error('Secrets not loaded. Call loadSecrets() first.');
    }

    const value = this.secrets[key];

    if (value === undefined) {
      console.warn(`Secret "${key}" not found`);
    }

    return value;
  }

  /**
   * Get all secrets (be careful with this in production)
   */
  getAll() {
    if (!this.isSecretsLoaded) {
      throw new Error('Secrets not loaded. Call loadSecrets() first.');
    }

    // Return a copy to prevent mutation
    return { ...this.secrets };
  }

  /**
   * Mask secrets for logging (prevents accidental exposure)
   */
  getMasked(key) {
    const value = this.get(key);

    if (!value) return '***MISSING***';

    if (key.toLowerCase().includes('secret') || 
        key.toLowerCase().includes('key') ||
        key.toLowerCase().includes('token') ||
        key.toLowerCase().includes('password')) {

      // Show first 4 chars and last 4 chars for debugging
      if (value.length >= 8) {
        return `${value.substring(0, 4)}...${value.substring(value.length - 4)}`;
      } else {
        return '***' + '*'.repeat(Math.min(value.length, 4));
      }
    }

    return value;
  }
}

