```

### 3. Implementation Example: AWS Secrets Manager

```javascript
// config/secrets/aws-secrets-manager.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class AWSSecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      if (response.SecretString) {
        return JSON.parse(response.SecretString);
      }

      if (response.SecretBinary) {
        return Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      throw new Error('No secret value found');
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async getApplicationSecrets() {
    const env = process.env.NODE_ENV || 'development';
    const secretName = `${env}/api/secrets`;

    return this.getSecret(secretName);
  }
}
```

