// Secure version of app.js with comprehensive security measures

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
require('dotenv').config();

const app = express();

// Security middleware stack
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  frameguard: { action: 'deny' },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Compression
app.use(compression());

// Body parsing middleware
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Input validation middleware
const validateId = (req, res, next) => {
  const { id } = req.params;
  if (id && !/^\d+$/.test(id)) {
    return res.status(400).json({ error: 'Invalid ID format' });
  }
  next();
};

const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Users endpoint with authentication middleware
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.split(' ')[1];

  // In production, validate against a proper auth service
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid token' });
  }

  next();
};

const authorize = (requiredRole) => {
  return (req, res, next) => {
    // Extract user role from token (simplified example)
    const userRole = req.headers['x-user-role'] || 'user';

    if (userRole !== requiredRole && userRole !== 'admin') {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// Secure users endpoint
app.get('/users', authenticate, authorize('admin'), (req, res) => {
  // Validate query parameters
  const { limit, offset } = req.query;

  if (limit && (isNaN(limit) || limit <= 0)) {
    return res.status(400).json({ error: 'Invalid limit parameter' });
  }

  if (offset && (isNaN(offset) || offset < 0)) {
    return res.status(400).json({ error: 'Invalid offset parameter' });
  }

  const safeLimit = Math.min(parseInt(limit) || 10, 100); // Max 100 records
  const safeOffset = parseInt(offset) || 0;

  // Mock database response with sanitized data
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      role: 'admin',
      createdAt: '2023-01-01T00:00:00.000Z'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      role: 'user',
      createdAt: '2023-01-02T00:00:00.000Z'
    },
  ];

  // Apply pagination
  const paginatedUsers = users.slice(safeOffset, safeOffset + safeLimit);

  // Return with metadata
  res.json({
    data: paginatedUsers,
    pagination: {
      total: users.length,
      limit: safeLimit,
      offset: safeOffset,
      hasMore: (safeOffset + safeLimit) < users.length
    }
  });
});

// Get user by ID with input validation
app.get('/users/:id', authenticate, validateId, (req, res) => {
  const userId = parseInt(req.params.id);

  // Validate user access (simplified example)
  const requestingUserId = req.headers['x-user-id'] || '1';

  if (userId.toString() !== requestingUserId) {
    return res.status(403).json({ error: 'Access denied' });
  }

  // Mock user data
  const user = { 
    id: userId, 
    name: 'Example User', 
    email: 'user@example.com',
    role: 'user'
  };

  res.json({ data: user });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak stack traces in production
  const errorResponse = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message,
    code: err.code || 'INTERNAL_ERROR'
  };

  if (process.env.NODE_ENV !== 'production' && err.stack) {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Resource not found',
    path: req.path,
    method: req.method
  });
});

// Server configuration
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown
const server = app.listen(PORT, HOST, () => {
  console.log(`Secure server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  server.close(() => process.exit(1));
});

// Handle SIGTERM for graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

