  }

  /**
   * Validate that all required secrets are present
   */
  async validateSecrets() {
    const { required, optional } = this.config.validation || { required: [], optional: [] };
    const missing = [];

    for (const secret of required) {
      if (!process.env[secret]) {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Log optional secrets that are missing (for debugging)
    for (const secret of optional) {
      if (!process.env[secret]) {
        console.warn(`Optional secret ${secret} is not set`);
      }
    }
  }

  /**
   * Fetch secrets from AWS Secrets Manager
   */
  async fetchFromAwsSecretsManager() {
    try {
      const response = await this.secretsManagerClient.getSecretValue({
        SecretId: this.config.secretName
      });

      let secrets;
      if ('SecretString' in response) {
        secrets = JSON.parse(response.SecretString);
      } else {
        // Handle binary secrets
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secrets = JSON.parse(buff.toString('utf-8'));
      }

      // Cache the secrets
      this.secretsCache.clear();
      for (const [key, value] of Object.entries(secrets)) {
        this.secretsCache.set(key, value);
      }

      this.lastFetchTime = Date.now();
      console.log('Secrets fetched from AWS Secrets Manager');

      // Audit log secret fetch
      this.auditLog('SECRETS_FETCH', {
        source: 'aws-secrets-manager',
        secretName: this.config.secretName,
        count: Object.keys(secrets).length
      });
    } catch (error) {
      console.error('Failed to fetch secrets from AWS Secrets Manager:', error);
      throw error;
    }
  }

  /**
   * Set up rotation polling for AWS Secrets Manager
   */
  setupRotationPolling() {
    const rotationInterval = this.config.cacheDuration || 300000; // 5 minutes default

    setInterval(async () => {
      try {
        await this.fetchFromAwsSecretsManager();
      } catch (error) {
        console.error('Secret rotation fetch failed:', error);
        // Don't throw - keep using cached secrets
      }
    }, rotationInterval);

    console.log(`Secret rotation polling enabled (${rotationInterval}ms interval)`);
  }

  /**
   * Get a secret value
   * @param {string} key - Secret key
   * @param {boolean} required - Whether the secret is required
   * @returns {Promise<string>} Secret value
   */
  async getSecret(key, required = true) {
    if (!this.initialized) {
      await this.initialize();
    }

    let value;

    // Try cache first
    if (this.secretsCache.has(key)) {
      value = this.secretsCache.get(key);
    } else if (this.config.source === 'env') {
      // Fall back to environment variables
      value = process.env[key];
    }

    // If still not found and required, throw error
    if (required && !value) {
      throw new Error(`Required secret '${key}' not found`);
    }

    // Audit log secret access
    this.auditLog('SECRET_ACCESS', {
      key,
      required,
      found: !!value,
      source: this.config.source
    });

    return value;
  }

  /**
   * Get multiple secrets at once
   * @param {string[]} keys - Array of secret keys
   * @returns {Promise<Object>} Object with secret values
   */
  async getSecrets(keys) {
    const secrets = {};

    for (const key of keys) {
      secrets[key] = await this.getSecret(key);
    }

    return secrets;
  }

  /**
   * Securely compare two tokens (timing-safe)
   * @param {string} inputToken - Token to verify
   * @param {string} secretKey - Key to fetch from secrets
   * @returns {Promise<boolean>} Whether tokens match
   */
  async verifyToken(inputToken, secretKey) {
    if (!inputToken) return false;

    const secretToken = await this.getSecret(secretKey);

    // Use timing-safe comparison
    return crypto.timingSafeEqual(
      Buffer.from(inputToken),
      Buffer.from(secretToken || '')
    );
  }

  /**
   * Generate a secure random token
   * @param {number} bytes - Number of bytes
   * @returns {string} Base64 encoded token
   */
  generateSecureToken(bytes = 32) {
    return crypto.randomBytes(bytes).toString('base64');
  }

  /**
   * Rotate a secret
   * @param {string} key - Secret key
   * @param {string} newValue - New secret value
   */
  async rotateSecret(key, newValue) {
    // This would update the secret in the secrets manager
    // Implementation depends on the secrets manager backend

    console.log(`Secret rotation requested for ${key}`);

    // Audit log rotation attempt
    this.auditLog('SECRET_ROTATION_ATTEMPT', {
      key,
      rotated: false,
      reason: 'Manual rotation not implemented'
    });

    throw new Error('Manual secret rotation not implemented for this backend');
  }

  /**
   * Audit logging for security events
   * @param {string} event - Event type
   * @param {Object} data - Event data
   */
  auditLog(event, data) {
    const timestamp = new Date().toISOString();
    const logEntry = {
      timestamp,
      event,
      environment: this.env,
      ...data
    };

    // In production, send to secure logging service
    // For local development, log to console
    if (this.env === 'production') {
      // Send to CloudWatch Logs, Splunk, etc.
      console.log('[AUDIT]', JSON.stringify(logEntry));
    } else {
      console.log('[AUDIT_DEV]', JSON.stringify(logEntry));
    }
  }

  /**
   * Clear all cached secrets (for testing)
   */
  clearCache() {
    this.secretsCache.clear();
    this.lastFetchTime = 0;
  }

  /**
   * Shutdown the secrets manager
   */
  async shutdown() {
    this.initialized = false;
    this.secretsCache.clear();

    // Close any connections
    if (this.secretsManagerClient) {
      // AWS SDK clients don't need explicit cleanup
      this.secretsManagerClient = null;
    }

    console.log('Secrets manager shut down');
  }
}

