  // Get CORS configuration from secrets manager
  const allowedOrigins = await secretsManager.getSecret('ALLOWED_ORIGINS', false) || 
                        'http://localhost:3000';

  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", "data:", "https:"],
