    },
    frameguard: { action: 'deny' },
    hsts: {
      maxAge: 31536000,
      includeSubDomains: true,
      preload: true
    }
  }));

  // CORS configuration
  app.use(cors({
    origin: allowedOrigins.split(','),
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400
  }));

  // Rate limiting - configuration from secrets if available
  const rateLimitConfig = {
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
  };

  // Try to get rate limit config from secrets
  try {
    const rateLimitMax = await secretsManager.getSecret('RATE_LIMIT_MAX_REQUESTS', false);
    const rateLimitWindow = await secretsManager.getSecret('RATE_LIMIT_WINDOW_MS', false);

    if (rateLimitMax) rateLimitConfig.max = parseInt(rateLimitMax);
    if (rateLimitWindow) rateLimitConfig.windowMs = parseInt(rateLimitWindow);
  } catch (error) {
    console.warn('Using default rate limit configuration');
  }

  const limiter = rateLimit(rateLimitConfig);
  app.use(limiter);

  // Compression
  app.use(compression());

  // Body parsing middleware
  app.use(express.json({ limit: '1mb' }));
  app.use(express.urlencoded({ extended: true, limit: '1mb' }));
};

