const startServer = async () => {
  try {
    const port = await secretsManager.getSecret('PORT', false) || 3000;
    const host = await secretsManager.getSecret('HOST', false) || '0.0.0.0';

    const server = app.listen(port, host, () => {
      console.log(`Secure server with secrets manager running on http://${host}:${port}`);
      console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`Secrets source: ${secretsManager.config.source}`);
    });

    // Graceful shutdown
    const gracefulShutdown = async () => {
      console.log('Shutting down gracefully...');

      // Shutdown secrets manager
      await secretsManager.shutdown();

      server.close(() => {
        console.log('Server closed');
        process.exit(0);
      });

      // Force shutdown after 10 seconds
      setTimeout(() => {
        console.error('Forcing shutdown after timeout');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', gracefulShutdown);
    process.on('SIGINT', gracefulShutdown);

    // Handle unhandled promise rejections
    process.on('unhandledRejection', async (reason, promise) => {
      console.error('Unhandled Rejection at:', promise, 'reason:', reason);
      await gracefulShutdown();
    });

    return server;
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Start the server
if (require.main === module) {
