  const client = new SecretsManager({
    region: process.env.AWS_REGION || 'us-east-1'
  });

  try {
    // Fetch database secrets
    const dbSecret = await client.getSecretValue({
      SecretId: process.env.DB_SECRET_NAME || 'prod/database'
    });
    const dbCreds = JSON.parse(dbSecret.SecretString);

    // Fetch API keys
    const apiSecret = await client.getSecretValue({
      SecretId: process.env.API_SECRET_NAME || 'prod/api-keys'
    });
    const apiCreds = JSON.parse(apiSecret.SecretString);

    return {
      databaseUrl: `postgres://${dbCreds.username}:${dbCreds.password}@${dbCreds.host}:${dbCreds.port}/${dbCreds.database}`,
      stripeKey: apiCreds.stripeKey,
      anthropicKey: apiCreds.anthropicKey,
      logfireToken: apiCreds.logfireToken
    };
  } catch (error) {
    console.error('Failed to load secrets:', error);
    throw error;
  }
}

// Load at application startup
let appSecrets;
loadSecrets().then(secrets => {
  appSecrets = secrets;
  app.listen(3000, () => {
    console.log('Server started with secure secrets');
  });
}).catch(err => {
  console.error('Failed to start server:', err);
  process.exit(1);
});
```

