#### 5. **Docker Secrets (for containerized environments):**

```javascript
const fs = require('fs').promises;
const path = require('path');

async function loadDockerSecrets() {
  const secretsDir = '/run/secrets';

  try {
    const secrets = {};
    const files = await fs.readdir(secretsDir);

    for (const file of files) {
      const secretPath = path.join(secretsDir, file);
      const content = await fs.readFile(secretPath, 'utf8');
      secrets[file] = content.trim();
    }

    return {
      databaseUrl: secrets['database_url'],
      stripeKey: secrets['stripe_secret_key'],
      awsAccessKeyId: secrets['aws_access_key_id'],
      awsSecretAccessKey: secrets['aws_secret_access_key']
    };
  } catch (error) {
    console.error('Docker secrets error:', error);
    throw error;
  }
}
```

