#### 7. **Environment Validation Module:**

```javascript
// config/validation.js
function validateEnvironment() {
  const requiredVars = [
    'NODE_ENV',
    'AWS_REGION', // If using AWS Secrets Manager
    'VAULT_ADDR', // If using HashiCorp Vault
  ];

  const missing = requiredVars.filter(varName => !process.env[varName]);

  if (missing.length > 0) {
    console.error(`Missing required environment variables: ${missing.join(', ')}`);
    process.exit(1);
  }

  // Validate NODE_ENV
  const allowedEnvs = ['development', 'test', 'production'];
  if (!allowedEnvs.includes(process.env.NODE_ENV)) {
    console.error(`Invalid NODE_ENV: ${process.env.NODE_ENV}. Must be one of: ${allowedEnvs.join(', ')}`);
    process.exit(1);
  }
}

module.exports = { validateEnvironment };
