function encodeForJSON(value) {
  return JSON.stringify(value).replace(/[<>&]/g, (char) => {
    switch (char) {
      case '<': return '\\u003c';
      case '>': return '\\u003e';
      case '&': return '\\u0026';
      default: return char;
    }
  });
