// ========== OPTION 3: Secret Manager Integration ==========
class SecretManager {
  constructor() {
    this.source = process.env.SECRETS_SOURCE || 'env'; // env, vault, aws, gcp
    this.cache = new Map();
  }

  async getSecret(name) {
    // Check cache first
    if (this.cache.has(name)) {
      return this.cache.get(name);
    }

    let value;

    switch (this.source) {
      case 'vault':
        value = await this.getFromVault(name);
        break;
      case 'aws':
        value = await this.getFromAWS(name);
        break;
      case 'gcp':
        value = await this.getFromGCP(name);
        break;
      default:
        value = process.env[name];
    }

    // Cache for 5 minutes
    if (value) {
      this.cache.set(name, value);
      setTimeout(() => this.cache.delete(name), 5 * 60 * 1000);
    }

    return value;
  }

  async getFromVault(secretPath) {
    // HashiCorp Vault integration
    const vault = require('node-vault')();
    try {
      const result = await vault.read(secretPath);
      return result.data.value;
    } catch (error) {
      console.error(`Vault error for ${secretPath}:`, error.message);
      return null;
    }
  }

  async getFromAWS(secretName) {
    // AWS Secrets Manager integration
    const AWS = require('aws-sdk');
    const secrets = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const result = await secrets
        .getSecretValue({ SecretId: secretName })
        .promise();
      return JSON.parse(result.SecretString);
    } catch (error) {
      console.error(`AWS Secrets Manager error for ${secretName}:`, error.message);
      return null;
    }
  }

  async getFromGCP(secretName) {
    // Google Cloud Secret Manager integration
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    const client = new SecretManagerServiceClient();

    try {
      const [version] = await client.accessSecretVersion({
        name: `projects/${process.env.GCP_PROJECT}/secrets/${secretName}/versions/latest`
      });
      return version.payload.data.toString();
    } catch (error) {
      console.error(`GCP Secret Manager error for ${secretName}:`, error.message);
      return null;
    }
  }
}

