// COMPREHENSIVE SECRET MANAGER IMPLEMENTATION
// Replaces insecure require('dotenv').config()

const crypto = require('crypto');

// Secret loading priority (highest to lowest):
// 1. Secret Manager (AWS, Azure, GCP, HashiCorp Vault)
// 2. Encrypted .env file (development only)
// 3. Environment variables (for CI/CD)
// 4. .env file with warnings (development only - LAST RESORT)

class SecretManager {
  constructor(options = {}) {
    this.secrets = new Map();
    this.loaded = false;
    this.options = {
      env: process.env.NODE_ENV || 'development',
      requireEncryption: options.requireEncryption || false,
      secretManager: options.secretManager || null, // 'aws', 'azure', 'gcp', 'vault'
      encryptedEnvFile: options.encryptedEnvFile || '.env.encrypted',
      fallbackToEnv: options.fallbackToEnv || false,
      ...options
    };

    this.validationRules = {
      API_TOKEN: { minLength: 32, maxLength: 256, required: true },
      JWT_SECRET: { minLength: 64, maxLength: 512, required: true },
      DATABASE_URL: { regex: /^postgres(ql)?:\/\/.+/i, required: true },
      AWS_ACCESS_KEY_ID: { regex: /^AKIA[0-9A-Z]{16}$/, required: false },
      STRIPE_SECRET_KEY: { regex: /^sk_(live|test)_[a-zA-Z0-9_\-]+$/, required: false }
    };
  }

  // Main method to load secrets
  async load() {
    if (this.loaded) return this.secrets;

    console.log(`🔐 Loading secrets for ${this.options.env} environment...`);

    try {
      // Try Secret Manager first
      if (this.options.secretManager) {
        await this.loadFromSecretManager();
      }

      // If still missing secrets, try encrypted .env file (dev only)
      if (this.options.env === 'development' && this.missingRequiredSecrets().length > 0) {
        await this.loadFromEncryptedEnv();
      }

      // Last resort: plain .env file with warnings
      if (this.options.fallbackToEnv && this.missingRequiredSecrets().length > 0) {
        this.loadFromPlainEnv();
      }

      // Validate all loaded secrets
      this.validateSecrets();

      // Set environment variables (temporary compatibility)
      this.setProcessEnv();

      this.loaded = true;
      console.log(`✅ Secrets loaded successfully`);

      // Log which method was used (for auditing)
      this.auditSecretSources();

      return this.secrets;
    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);

      // Don't expose details in production
      if (this.options.env === 'production') {
        throw new Error('Secret configuration failed - check secret manager setup');
      }
      throw error;
    }
  }

  // AWS Secrets Manager implementation
  async loadFromSecretManager() {
    console.log('🔄 Attempting to load from secret manager...');

    switch (this.options.secretManager) {
      case 'aws':
        return await this.loadFromAWSSecretsManager();
      case 'azure':
        return await this.loadFromAzureKeyVault();
      case 'gcp':
        return await this.loadFromGCPSecretManager();
      case 'vault':
        return await this.loadFromHashiCorpVault();
      default:
        throw new Error(`Unsupported secret manager: ${this.options.secretManager}`);
    }
  }

  async loadFromAWSSecretsManager() {
    // AWS Secrets Manager implementation
    const { SecretsManager } = require('aws-sdk');

    const client = new SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      // Try environment-specific secret first
      const secretName = `app/${this.options.env}/secrets`;
      const response = await client.getSecretValue({ SecretId: secretName }).promise();

      if (response.SecretString) {
        const secrets = JSON.parse(response.SecretString);

        // Validate and store
        for (const [key, value] of Object.entries(secrets)) {
          if (value && typeof value === 'string') {
            this.secrets.set(key, value);
          }
        }

        console.log(`✅ Loaded secrets from AWS Secrets Manager: ${secretName}`);
        return true;
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        console.log(`ℹ️ Secret ${secretName} not found in AWS Secrets Manager`);
        return false;
      }
      throw error;
    }
  }

  async loadFromEncryptedEnv() {
    console.log('🔐 Attempting to load from encrypted .env file...');

    const fs = require('fs');
    const path = require('path');

    const encryptedFilePath = path.join(process.cwd(), this.options.encryptedEnvFile);

    if (!fs.existsSync(encryptedFilePath)) {
      console.log(`ℹ️ Encrypted .env file not found: ${encryptedFilePath}`);
      return false;
    }

    // Get decryption key from environment or KMS
    const encryptionKey = process.env.ENCRYPTION_KEY;
    if (!encryptionKey) {
      console.warn('⚠️ ENCRYPTION_KEY not set, cannot decrypt .env file');
      return false;
    }

    try {
      const encryptedData = fs.readFileSync(encryptedFilePath, 'utf8');

      // Simple AES decryption (in production, use KMS or similar)
      const decipher = crypto.createDecipheriv(
        'aes-256-gcm',
        crypto.scryptSync(encryptionKey, 'salt', 32),
        Buffer.alloc(16, 0) // IV - should be stored with encrypted data
      );

      let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
      decrypted += decipher.final('utf8');

      // Parse as .env format
      const lines = decrypted.split('\n');
      for (const line of lines) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          const value = valueParts.join('=').trim();
          // Remove quotes if present
          const cleanValue = value.replace(/^['"]|['"]$/g, '');
          this.secrets.set(key.trim(), cleanValue);
        }
      }

      console.log(`✅ Loaded secrets from encrypted .env file`);
      return true;
    } catch (error) {
      console.error('❌ Failed to decrypt .env file:', error.message);
      return false;
    }
  }

  loadFromPlainEnv() {
    console.warn('⚠️ WARNING: Loading from plain .env file - NOT RECOMMENDED');

    // Only allow in development
    if (this.options.env === 'production') {
      throw new Error('Cannot load from plain .env file in production');
    }

    try {
      require('dotenv').config();

      // Copy from process.env
      for (const [key, value] of Object.entries(process.env)) {
        if (value && this.isSecretKey(key)) {
          this.secrets.set(key, value);
        }
      }

      console.log('⚠️ Loaded from plain .env file (insecure - for development only)');
      return true;
    } catch (error) {
      console.error('❌ Failed to load from .env:', error);
      return false;
    }
  }

  // Validation methods
  validateSecrets() {
    const missing = this.missingRequiredSecrets();
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Validate each secret against rules
    for (const [key, value] of this.secrets.entries()) {
      const rule = this.validationRules[key];
      if (rule) {
        this.validateSecret(key, value, rule);
      }
    }

    // Additional security checks
    this.performSecurityChecks();
  }

  validateSecret(key, value, rule) {
    if (!value && rule.required) {
      throw new Error(`Required secret ${key} is empty`);
    }

    if (value) {
      // Length validation
      if (rule.minLength && value.length < rule.minLength) {
        throw new Error(`Secret ${key} is too short (min: ${rule.minLength})`);
      }
      if (rule.maxLength && value.length > rule.maxLength) {
        throw new Error(`Secret ${key} is too long (max: ${rule.maxLength})`);
      }

      // Regex validation
      if (rule.regex && !rule.regex.test(value)) {
        throw new Error(`Secret ${key} has invalid format`);
      }

      // Security checks
      if (this.containsExposedPattern(value)) {
        console.warn(`⚠️ Warning: Secret ${key} may contain exposed pattern`);
      }
    }
  }

  // Security checks
  containsExposedPattern(value) {
    const exposedPatterns = [
      /CANARY/i,
      /test/i,
      /example/i,
      /password/i,
      /123456/i,
      /admin/i
    ];

    return exposedPatterns.some(pattern => pattern.test(value));
  }

  performSecurityChecks() {
    // Check for duplicate or weak secrets
    const values = Array.from(this.secrets.values());
    const uniqueValues = new Set(values);

    if (uniqueValues.size < values.length) {
      console.warn('⚠️ Warning: Duplicate secret values detected');
    }

    // Check if any secret looks like default/example
    for (const [key, value] of this.secrets.entries()) {
      if (value.includes('example') || value.includes('changeme') || value.includes('placeholder')) {
        console.warn(`⚠️ Warning: Secret ${key} appears to be a placeholder`);
      }
    }
  }

  // Utility methods
  missingRequiredSecrets() {
    return Object.entries(this.validationRules)
      .filter(([key, rule]) => rule.required && !this.secrets.has(key))
      .map(([key]) => key);
  }

  isSecretKey(key) {
    return key.includes('SECRET') || 
           key.includes('KEY') || 
           key.includes('TOKEN') || 
           key.includes('PASSWORD') ||
           key.includes('_URL') && key.includes('DATABASE');
  }

  setProcessEnv() {
    // Temporary compatibility layer
    for (const [key, value] of this.secrets.entries()) {
      if (!process.env[key]) {
        process.env[key] = value;
      }
    }
  }

  auditSecretSources() {
    // Log where secrets came from for auditing
    console.log('📋 Secret Sources:');
    console.log(`  Environment: ${this.options.env}`);
    console.log(`  Secret Manager: ${this.options.secretManager || 'none'}`);
    console.log(`  Encrypted Env: ${this.secrets.size > 0 ? 'used' : 'not used'}`);
    console.log(`  Plain Env: ${this.options.fallbackToEnv ? 'available' : 'disabled'}`);
  }

  // Get secret with audit logging
  get(key, context = 'unknown') {
    if (!this.secrets.has(key)) {
      throw new Error(`Secret ${key} not found`);
    }

    // Log access in production
    if (this.options.env === 'production') {
      console.log(`🔑 Secret accessed: ${key} by ${context} at ${new Date().toISOString()}`);
    }

    return this.secrets.get(key);
