```javascript
// migrate-to-encrypted.js
const fs = require('fs');
const crypto = require('crypto');
const readline = require('readline');

async function migrate() {
  // Read existing .env
  const envContent = fs.readFileSync('.env', 'utf8');

  // Generate encryption key
  const key = crypto.randomBytes(32);
  fs.writeFileSync('.encryption.key', key.toString('hex'));
  console.log('🔑 Generated encryption key: .encryption.key');

  // Encrypt
  const cipher = crypto.createCipheriv('aes-256-gcm', key, Buffer.alloc(16, 0));
  let encrypted = cipher.update(envContent, 'utf8', 'hex');
  encrypted += cipher.final('hex');

  // Write encrypted file
  fs.writeFileSync('.env.encrypted', encrypted);

  // Remove plain .env
  fs.unlinkSync('.env');

  console.log('✅ Migrated to encrypted .env.encrypted');
  console.log('⚠️ Add .encryption.key to .gitignore!');
}
```

### **2. Migrate to AWS Secrets Manager**
```javascript
// migrate-to-aws.js
const fs = require('fs');
const { SecretsManager } = require('aws-sdk');

async function migrate() {
  const envContent = fs.readFileSync('.env', 'utf8');
  const secrets = {};

  // Parse .env
  envContent.split('\n').forEach(line => {
    const [key, ...value] = line.split('=');
    if (key && value.length > 0) {
      secrets[key.trim()] = value.join('=').trim().replace(/^['"]|['"]$/g, '');
    }
  });

  // Upload to AWS
  const client = new SecretsManager();
  await client.createSecret({
    Name: `app/${process.env.NODE_ENV || 'development'}/secrets`,
    SecretString: JSON.stringify(secrets)
  }).promise();

  console.log('✅ Migrated to AWS Secrets Manager');
  console.log('⚠️ Remove .env file after verification');
}
```

