      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
  }

  async getSecret(secretName, useCache = true) {
    if (useCache && this.cache.has(secretName)) {
      return this.cache.get(secretName);
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({
          SecretId: secretName,
        })
      );

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      if (useCache) {
        this.cache.set(secretName, secretValue);
      }

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  // Rotate cache for dynamic secrets
  invalidateCache(secretName) {
    this.cache.delete(secretName);
  }
}

// Singleton instance
module.exports = new SecretsManager();
```

