// security-middleware.js
const { body, query, param, validationResult } = require('express-validator');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Input validation middleware
const validateUserInput = [
  body('email').isEmail().normalizeEmail(),
  body('name').trim().escape().isLength({ min: 1, max: 100 }),
  body('id').isInt({ gt: 0 }),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

const validateQueryParams = [
  query('page').optional().isInt({ gt: 0 }).toInt(),
  query('limit').optional().isInt({ gt: 0, lt: 100 }).toInt(),
  query('search').optional().trim().escape(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

// SQL Injection protection
const sanitizeForSQL = (req, res, next) => {
  const sanitize = (obj) => {
    if (typeof obj === 'string') {
      // Remove common SQL injection patterns
      return obj.replace(/['";\\\-\-]/g, '');
    }
    if (Array.isArray(obj)) {
      return obj.map(sanitize);
    }
    if (obj && typeof obj === 'object') {
      const sanitized = {};
      for (const key in obj) {
        sanitized[key] = sanitize(obj[key]);
      }
      return sanitized;
    }
    return obj;
  };

  req.body = sanitize(req.body);
  req.query = sanitize(req.query);
  req.params = sanitize(req.params);
  next();
};

module.exports = {
  validateUserInput,
  validateQueryParams,
  sanitizeForSQL
};

// auth-middleware.js
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const crypto = require('crypto');

const JWT_SECRET = process.env.JWT_SECRET || crypto.randomBytes(64).toString('hex');
const ACCESS_TOKEN_EXPIRY = '15m';
const REFRESH_TOKEN_EXPIRY = '7d';

// API key authentication middleware
const apiKeyAuth = (req, res, next) => {
  const apiKey = req.headers['x-api-key'] || req.query.api_key;
  const validApiKeys = process.env.API_KEYS ? process.env.API_KEYS.split(',') : [];

  if (!apiKey) {
    return res.status(401).json({ error: 'API key required' });
  }

  if (!validApiKeys.includes(apiKey.trim())) {
    console.warn(`Invalid API key attempt from ${req.ip}`);
    return res.status(403).json({ error: 'Invalid API key' });
  }

  req.apiKey = apiKey;
  next();
};

// JWT authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      console.warn(`JWT verification failed: ${err.message} from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid token' });
    }

    req.user = user;
    next();
  });
};

// Role-based authorization middleware
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      console.warn(`Unauthorized role access attempt: ${req.user.role} from ${req.ip}`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// Rate limiting by IP
const rateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});

// Rate limiting by API key
const apiKeyRateLimiter = (maxRequests) => rateLimit({
  windowMs: 15 * 60 * 1000,
  max: maxRequests,
  keyGenerator: (req) => req.apiKey || req.ip,
  message: { error: 'Rate limit exceeded for this API key' },
});

// Function to generate password hash
const hashPassword = async (password) => {
  const saltRounds = 12;
  return await bcrypt.hash(password, saltRounds);
};

// Function to verify password
const verifyPassword = async (password, hash) => {
  return await bcrypt.compare(password, hash);
};

// Generate JWT tokens
const generateTokens = (user) => {
  const accessToken = jwt.sign(
    { userId: user.id, email: user.email, role: user.role },
    JWT_SECRET,
    { expiresIn: ACCESS_TOKEN_EXPIRY }
  );

  const refreshToken = jwt.sign(
    { userId: user.id },
    JWT_SECRET,
    { expiresIn: REFRESH_TOKEN_EXPIRY }
  );

  return { accessToken, refreshToken };
};

module.exports = {
  apiKeyAuth,
  authenticateToken,
  authorize,
  rateLimiter,
  apiKeyRateLimiter,
  hashPassword,
  verifyPassword,
  generateTokens,
  JWT_SECRET
};

// app-secure.js - Secured version of app.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const compression = require('compression');
const morgan = require('morgan');
const { sanitizeForSQL, validateQueryParams } = require('./security-middleware');
const { authenticateToken, authorize, rateLimiter, apiKeyRateLimiter } = require('./auth-middleware');

const app = express();

// ========== SECURITY CONFIGURATION ==========

// 1. Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  crossOriginEmbedderPolicy: false
}));

// 2. Configure CORS
const allowedOrigins = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',') 
  : ['http://localhost:3001'];

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      console.warn(`Blocked CORS request from origin: ${origin}`);
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-API-Key']
}));

// 3. Rate limiting for all requests
app.use(rateLimiter);

// 4. Prevent HTTP Parameter Pollution
app.use(require('hpp')());

// 5. Compression for performance
app.use(compression());

// 6. Request logging (configured for production)
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400, // Only log errors in production
  stream: process.stderr
}));

// 7. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 8. XSS protection middleware
app.use((req, res, next) => {
  // Set XSS protection headers
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});

// ========== INPUT VALIDATION MIDDLEWARE ==========
app.use(sanitizeForSQL);

// ========== SECURED ROUTES ==========

// Public health endpoint with rate limiting
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Secured users endpoint - requires authentication
app.get('/users', 
  authenticateToken, 
  authorize('admin', 'user'), 
  validateQueryParams,
  (req, res) => {
    // Example: Mask sensitive data
    const maskedUsers = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'a***e@example.com', // Masked email
        role: 'user',
        createdAt: '2024-01-01T00:00:00.000Z'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'b**@example.com', // Masked email
        role: 'admin',
        createdAt: '2024-01-02T00:00:00.000Z'
      },
    ];

    // Apply pagination if provided
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const paginatedUsers = maskedUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: maskedUsers.length,
        totalPages: Math.ceil(maskedUsers.length / limit)
      }
    });
  }
);

// API key authenticated endpoint
app.get('/secure-data',
  apiKeyAuth,
  apiKeyRateLimiter(50), // 50 requests per 15 minutes per API key
  (req, res) => {
    res.json({
      message: 'This is secure data accessible only with valid API key',
      accessedAt: new Date().toISOString(),
      apiKey: req.apiKey.slice(0, 4) + '...' // Don't expose full key
    });
  }
);

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`Error: ${err.message}`, {
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    timestamp: new Date().toISOString()
  });

  // Don't expose stack traces in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An error occurred'
  };

  res.status(err.status || 500).json(errorResponse);
});

// ========== SERVER CONFIGURATION ==========

const PORT = process.env.PORT || 3000;
const HOST = '0.0.0.0';

// Security: Ensure we're not running as root in production
if (process.env.NODE_ENV === 'production') {
  if (process.getuid && process.getuid() === 0) {
    console.error('Warning: Running as root in production is a security risk!');
    process.exit(1);
  }
}

const server = app.listen(PORT, HOST, () => {
  console.log(`Secure server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);

  // Security audit logging
  console.log('Security features enabled:');
  console.log('- Helmet security headers');
  console.log('- CORS with origin restrictions');
  console.log('- Rate limiting');
  console.log('- Input validation & sanitization');
  console.log('- JWT authentication');
  console.log('- API key authentication');
  console.log('- Error masking in production');
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Unhandled promise rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to exit here or alert monitoring
});

module.exports = app;

