/**
 * Security Audit Script
 * Run this to audit your application for security issues
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

class SecurityAudit {
  constructor() {
    this.issues = [];
    this.warnings = [];
    this.passed = [];
  }

  logIssue(severity, issue, recommendation) {
    this.issues.push({ severity, issue, recommendation });
    console.log(`❌ ${severity}: ${issue}`);
    console.log(`   💡 Recommendation: ${recommendation}\n`);
  }

  logWarning(warning, recommendation) {
    this.warnings.push({ warning, recommendation });
    console.log(`⚠️  Warning: ${warning}`);
    console.log(`   💡 Suggestion: ${recommendation}\n`);
  }

  logPassed(check) {
    this.passed.push(check);
    console.log(`✅ ${check}\n`);
  }

  checkForSensitiveFiles() {
    console.log('🔍 Checking for sensitive files...');

    const sensitiveFiles = [
      '.env',
      '.env.production',
      '.env.development',
      'config.json',
      'secrets.json',
      'credentials.json',
      'firebase-key.json',
      'service-account-key.json'
    ];

    for (const file of sensitiveFiles) {
      if (fs.existsSync(file)) {
        const stats = fs.statSync(file);
        const perms = stats.mode.toString(8).slice(-3);

        this.logWarning(
          `Sensitive file found: ${file} (Permissions: ${perms})`,
          `Move ${file} to secure storage, add to .gitignore, and set restrictive permissions (600)`
        );
      }
    }

    this.logPassed('Completed sensitive files check');
  }

  checkFilePermissions() {
    console.log('🔍 Checking file permissions...');

    const filesToCheck = [
      'app.js',
      'app-secure.js',
      'package.json',
      '*.js'
    ];

    // Check for world-writable files
    try {
      const result = execSync('find . -type f -perm /o+w -name "*.js" -o -name "*.json"', { encoding: 'utf8' });
      if (result.trim()) {
        this.logIssue(
          'HIGH',
          'World-writable files found',
          'Remove world-writable permissions: chmod o-w <filename>'
        );
        console.log(`   Files: ${result}`);
      }
    } catch (error) {
      // No files found or error
    }

    this.logPassed('Completed file permissions check');
  }

  checkDependencies() {
    console.log('🔍 Checking dependencies...');

    if (!fs.existsSync('package.json')) {
      this.logIssue('CRITICAL', 'No package.json found', 'Create a package.json with security-focused dependencies');
      return;
    }

    try {
      // Check for vulnerable dependencies
      execSync('npm audit --audit-level=moderate', { stdio: 'inherit' });
      this.logPassed('Dependency audit completed');
    } catch (error) {
      this.logIssue(
        'HIGH',
        'Vulnerable dependencies found',
        'Run "npm audit fix" and update dependencies regularly'
      );
    }

    // Check for security-focused dependencies
    const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));
    const securityDeps = [
      'helmet',
      'express-validator',
      'express-rate-limit',
      'bcrypt',
      'jsonwebtoken',
      'cors'
    ];

    const missingDeps = securityDeps.filter(dep => !packageJson.dependencies?.[dep]);
    if (missingDeps.length > 0) {
      this.logIssue(
        'MEDIUM',
        `Missing security dependencies: ${missingDeps.join(', ')}`,
        'Install missing security packages: npm install ' + missingDeps.join(' ')
      );
    } else {
      this.logPassed('All recommended security dependencies are installed');
    }
  }

  checkCodeSecurity() {
    console.log('🔍 Checking code for security issues...');

    // Read original app.js
    if (fs.existsSync('app.js')) {
      const code = fs.readFileSync('app.js', 'utf8');

      // Check for common security issues
      const checks = [
        {
          pattern: /express\.json\(\)/,
          issue: 'Missing body parser size limits',
          recommendation: 'Use express.json({ limit: "10kb" }) to prevent DoS attacks'
        },
        {
          pattern: /app\.listen\((\d+)/,
          issue: 'Hardcoded port without environment variable',
          recommendation: 'Use process.env.PORT || 3000'
        },
        {
          pattern: /console\.log\(/,
          issue: 'Potential sensitive data logging',
          recommendation: 'Use structured logging library (winston/pino) and avoid logging sensitive data'
        },
        {
          pattern: /res\.send\(.*req\.(body|query|params)/,
          issue: 'Potential XSS vulnerability',
          recommendation: 'Always sanitize and validate user input before echoing it back'
        }
      ];

      for (const check of checks) {
        if (check.pattern.test(code)) {
          this.logWarning(check.issue, check.recommendation);
        }
      }
    }

    this.logPassed('Completed code security check');
  }

  checkEnvironment() {
    console.log('🔍 Checking environment configuration...');

    if (!fs.existsSync('.env.example')) {
      this.logWarning(
        'No .env.example file found',
        'Create .env.example with example configuration (see provided example)'
      );
    }

    if (!fs.existsSync('.gitignore')) {
      this.logIssue(
        'MEDIUM',
        'No .gitignore file found',
        'Create .gitignore to prevent committing sensitive files'
      );
    } else {
      const gitignore = fs.readFileSync('.gitignore', 'utf8');
      if (!gitignore.includes('.env') || !gitignore.includes('node_modules')) {
        this.logWarning(
          '.gitignore may be missing important entries',
          'Ensure .env, .env.*, node_modules, and other sensitive files are in .gitignore'
        );
      }
    }

    this.logPassed('Completed environment check');
  }

  generateReport() {
    console.log('\n' + '='.repeat(60));
    console.log('🚀 SECURITY AUDIT REPORT');
    console.log('='.repeat(60));

    console.log(`\n📊 Summary:`);
    console.log(`   ✅ Passed checks: ${this.passed.length}`);
    console.log(`   ⚠️  Warnings: ${this.warnings.length}`);
    console.log(`   ❌ Issues: ${this.issues.length}`);

    if (this.issues.length > 0) {
      console.log(`\n🔴 CRITICAL & HIGH SEVERITY ISSUES:`);
      this.issues
        .filter(item => item.severity === 'CRITICAL' || item.severity === 'HIGH')
        .forEach(item => {
          console.log(`   • ${item.issue}`);
        });
    }

    if (this.warnings.length > 0) {
      console.log(`\n🟡 WARNINGS:`);
      this.warnings.forEach(item => {
        console.log(`   • ${item.warning}`);
      });
    }

    console.log(`\n📝 RECOMMENDATIONS:`);
    console.log(`   1. Review and fix all issues above`);
    console.log(`   2. Run the secure version: node app-secure.js`);
    console.log(`   3. Configure environment variables in .env file`);
    console.log(`   4. Install dependencies: npm install`);
    console.log(`   5. Enable HTTPS in production`);
    console.log(`   6. Set up monitoring and alerting`);
    console.log(`   7. Regularly run security audits and penetration tests`);

    console.log('\n' + '='.repeat(60));
  }

  runAllChecks() {
    console.log('🔐 Starting Security Audit...\n');

    this.checkForSensitiveFiles();
    this.checkFilePermissions();
    this.checkDependencies();
    this.checkCodeSecurity();
    this.checkEnvironment();

    this.generateReport();
  }
}

// Run the audit
const audit = new SecurityAudit();
audit.runAllChecks();

// Exit with appropriate code
if (audit.issues.filter(i => i.severity === 'CRITICAL' || i.severity === 'HIGH').length > 0) {
  process.exit(1);
} else {
  process.exit(0);
}

