// secrets-manager-aws.js
// AWS Secrets Manager integration for production

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

class AWSSecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      // AWS credentials should come from IAM role, not environment variables
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes cache
  }

  async getSecret(secretName, versionStage = 'AWSCURRENT') {
    // Check cache first
    const cacheKey = `${secretName}:${versionStage}`;
    const cached = this.cache.get(cacheKey);

    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: versionStage,
      });

      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = response.SecretString;
      } else {
        // For binary secrets
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = buff.toString('ascii');
      }

      // Parse if it's JSON
      try {
        secretValue = JSON.parse(secretValue);
      } catch (e) {
        // Not JSON, keep as string
      }

      // Cache the result
      this.cache.set(cacheKey, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);

      // In development, fall back to environment variables
      if (process.env.NODE_ENV === 'development') {
        console.warn(`Falling back to environment variable for ${secretName}`);
        return process.env[secretName];
      }

      throw new Error(`Secret ${secretName} not available: ${error.message}`);
    }
  }

  async getDatabaseConfig() {
    const secret = await this.getSecret('prod/database/config');
    return {
      host: secret.host,
      port: secret.port,
      database: secret.dbname,
      username: secret.username,
      password: secret.password,
      ssl: true
    };
  }

  async getJWTConfig() {
    const secret = await this.getSecret('prod/jwt/secrets');
    return {
      accessSecret: secret.access_token_secret,
      refreshSecret: secret.refresh_token_secret,
      accessExpiry: '15m',
      refreshExpiry: '7d'
    };
  }

  async getAPIKeys() {
    const secret = await this.getSecret('prod/api/keys');
    return secret.keys.split(',').map(key => key.trim());
  }

  async getThirdPartyKeys() {
    const secret = await this.getSecret('prod/thirdparty/keys');
    return {
      stripe: secret.stripe_secret_key,
      sendgrid: secret.sendgrid_api_key,
      anthropic: secret.anthropic_api_key
    };
  }

  // Rotate secret (initiate rotation)
  async rotateSecret(secretName) {
    try {
      const { SecretsManagerClient, RotateSecretCommand } = require('@aws-sdk/client-secrets-manager');
      const rotateClient = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const command = new RotateSecretCommand({
        SecretId: secretName,
        RotationRules: {
          AutomaticallyAfterDays: 90 // Rotate every 90 days
        }
      });

      await rotateClient.send(command);
      console.log(`Rotation initiated for secret: ${secretName}`);

      // Clear cache for this secret
      Array.from(this.cache.keys())
        .filter(key => key.startsWith(secretName))
        .forEach(key => this.cache.delete(key));

      return true;
    } catch (error) {
      console.error(`Failed to rotate secret ${secretName}:`, error);
      return false;
    }
  }

  // Get secret metadata (rotation status, created date, etc.)
  async getSecretMetadata(secretName) {
    try {
      const { SecretsManagerClient, DescribeSecretCommand } = require('@aws-sdk/client-secrets-manager');
      const metadataClient = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const command = new DescribeSecretCommand({
        SecretId: secretName
      });

      const response = await metadataClient.send(command);
      return {
        name: response.Name,
        description: response.Description,
        lastChanged: response.LastChangedDate,
        lastAccessed: response.LastAccessedDate,
        rotationEnabled: response.RotationEnabled,
        nextRotation: response.NextRotationDate,
        tags: response.Tags
      };
    } catch (error) {
      console.error(`Failed to get metadata for ${secretName}:`, error);
      return null;
    }
  }
}

// Environment-based secrets loader
class SecretsLoader {
  constructor() {
    this.secretsManager = null;
    this.secrets = {};
  }

  async initialize() {
    if (process.env.NODE_ENV === 'production') {
      // Use AWS Secrets Manager in production
      this.secretsManager = new AWSSecretsManager();

      // Load all required secrets
      await this.loadProductionSecrets();
    } else {
      // Use environment variables in development
      await this.loadDevelopmentSecrets();
    }
  }

  async loadProductionSecrets() {
    try {
      this.secrets = {
        jwt: await this.secretsManager.getJWTConfig(),
        database: await this.secretsManager.getDatabaseConfig(),
        apiKeys: await this.secretsManager.getAPIKeys(),
        thirdParty: await this.secretsManager.getThirdPartyKeys(),
        // Add other secrets as needed
      };
    } catch (error) {
      console.error('Failed to load production secrets:', error);
      throw error;
    }
  }

  async loadDevelopmentSecrets() {
    // Fallback to environment variables with validation
    this.secrets = {
      jwt: {
        accessSecret: this.validateSecret(process.env.JWT_SECRET, 'JWT_SECRET'),
        refreshSecret: this.validateSecret(process.env.JWT_REFRESH_SECRET, 'JWT_REFRESH_SECRET'),
        accessExpiry: process.env.JWT_ACCESS_EXPIRY || '15m',
        refreshExpiry: process.env.JWT_REFRESH_EXPIRY || '7d'
      },
      database: {
        host: process.env.DB_HOST || 'localhost',
        port: process.env.DB_PORT || 5432,
        database: process.env.DB_NAME || 'app_dev',
        username: process.env.DB_USER || 'postgres',
        password: process.env.DB_PASSWORD || '',
        ssl: process.env.DB_SSL === 'true'
      },
      apiKeys: process.env.API_KEYS ? process.env.API_KEYS.split(',').map(k => k.trim()) : [],
      thirdParty: {
        stripe: process.env.STRIPE_SECRET_KEY,
        sendgrid: process.env.SENDGRID_API_KEY,
        anthropic: process.env.ANTHROPIC_API_KEY
      }
    };
  }

  validateSecret(secret, name) {
    if (!secret || secret.length < 32) {
      if (process.env.NODE_ENV === 'production') {
        throw new Error(`Invalid ${name}: Must be at least 32 characters in production`);
      }
      console.warn(`Warning: ${name} is weak or missing. Generating temporary secret.`);
      return crypto.randomBytes(32).toString('hex');
    }

    // Check if it's a default/example value
    if (secret.includes('example') || secret.includes('change-me') || secret.includes('your-')) {
      console.warn(`Warning: ${name} appears to be a default value`);
    }

    return secret;
  }

  getSecret(key) {
    return this.secrets[key];
  }

  getAllSecrets() {
    return { ...this.secrets };
  }

  // For testing - never use in production
  _setTestSecret(key, value) {
    if (process.env.NODE_ENV === 'test') {
      this.secrets[key] = value;
    }
  }
}

module.exports = new SecretsLoader();

// secrets-manager.js
// Secure secrets management with multiple backends

const crypto = require('crypto');

class SecretsManager {
  constructor() {
    this.backend = this.detectBackend();
    this.secrets = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
    this.defaultSecrets = {
      // Development defaults - NEVER use in production
      JWT_SECRET: 'dev-jwt-secret-change-in-production-' + crypto.randomBytes(16).toString('hex'),
      API_KEYS: 'dev-api-key-1,dev-api-key-2',
      DATABASE_URL: 'postgres://postgres:postgres@localhost:5432/app_dev'
    };
  }

  detectBackend() {
    // Determine which secrets backend to use
    if (process.env.AWS_SECRETS_MANAGER_ENABLED === 'true') {
      return 'aws';
    } else if (process.env.HASHICORP_VAULT_ADDR) {
      return 'vault';
    } else if (process.env.GOOGLE_SECRET_MANAGER_PROJECT) {
      return 'google';
    } else if (process.env.AZURE_KEY_VAULT_NAME) {
      return 'azure';
    } else {
      return 'env'; // Fallback to environment variables
    }
  }

  async initialize() {
    console.log(`Using secrets backend: ${this.backend}`);

    switch (this.backend) {
      case 'aws':
        await this.initializeAWS();
        break;
      case 'vault':
        await this.initializeVault();
        break;
      case 'env':
        await this.initializeEnv();
        break;
      default:
        throw new Error(`Unsupported secrets backend: ${this.backend}`);
    }

    await this.validateSecrets();
  }

  async initializeAWS() {
    // Lazy load AWS SDK to avoid unnecessary dependencies
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

    this.awsClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    // Load critical secrets
    await this.loadAWSSecret('jwt');
    await this.loadAWSSecret('database');
    await this.loadAWSSecret('api');
    await this.loadAWSSecret('thirdparty');
  }

  async loadAWSSecret(secretType) {
    const secretName = `${process.env.APP_NAME || 'app'}/${process.env.NODE_ENV || 'development'}/${secretType}`;

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
      });

      const response = await this.awsClient.send(command);
      let secretValue = response.SecretString;

      try {
        secretValue = JSON.parse(secretValue);
      } catch (e) {
        // Not JSON, keep as is
      }

      this.secrets.set(secretType, {
        value: secretValue,
        timestamp: Date.now()
      });

      console.log(`Loaded ${secretType} secret from AWS Secrets Manager`);
    } catch (error) {
      console.error(`Failed to load ${secretType} secret from AWS:`, error.message);
      // Fall back to environment variables
      await this.loadEnvSecret(secretType);
    }
  }

  async initializeVault() {
    // HashiCorp Vault implementation
    const vault = require('node-vault')({
      apiVersion: 'v1',
      endpoint: process.env.HASHICORP_VAULT_ADDR,
      token: process.env.HASHICORP_VAULT_TOKEN
    });

    this.vaultClient = vault;

    // Load secrets from Vault
    const secrets = await Promise.all([
      this.loadVaultSecret('secret/jwt'),
      this.loadVaultSecret('secret/database'),
      this.loadVaultSecret('secret/api'),
      this.loadVaultSecret('secret/thirdparty')
    ]);
  }

  async loadVaultSecret(path) {
    try {
      const result = await this.vaultClient.read(path);
      const secretType = path.split('/').pop();
      this.secrets.set(secretType, {
        value: result.data,
        timestamp: Date.now()
      });
      console.log(`Loaded ${secretType} secret from Vault`);
    } catch (error) {
      console.error(`Failed to load ${path} from Vault:`, error.message);
      await this.loadEnvSecret(secretType);
    }
  }

  async initializeEnv() {
    console.warn('⚠️  Using environment variables for secrets - not recommended for production!');

    // Load all secrets from environment variables
    await this.loadEnvSecret('jwt');
    await this.loadEnvSecret('database');
    await this.loadEnvSecret('api');
    await this.loadEnvSecret('thirdparty');
  }

  async loadEnvSecret(secretType) {
    let secretValue;

    switch (secretType) {
      case 'jwt':
        secretValue = {
          access: process.env.JWT_ACCESS_SECRET || this.defaultSecrets.JWT_SECRET,
          refresh: process.env.JWT_REFRESH_SECRET || this.defaultSecrets.JWT_SECRET + '-refresh',
          accessExpiry: process.env.JWT_ACCESS_EXPIRY || '15m',
          refreshExpiry: process.env.JWT_REFRESH_EXPIRY || '7d'
        };
        break;

      case 'database':
        secretValue = {
          url: process.env.DATABASE_URL || this.defaultSecrets.DATABASE_URL,
          ssl: process.env.DB_SSL === 'true',
          poolSize: parseInt(process.env.DB_POOL_SIZE) || 10
        };
        break;

      case 'api':
        secretValue = {
          keys: process.env.API_KEYS ? process.env.API_KEYS.split(',') : this.defaultSecrets.API_KEYS.split(','),
          rateLimit: parseInt(process.env.API_RATE_LIMIT) || 100
        };
        break;

      case 'thirdparty':
        secretValue = {
          stripe: process.env.STRIPE_SECRET_KEY,
          sendgrid: process.env.SENDGRID_API_KEY,
          twilio: process.env.TWILIO_AUTH_TOKEN,
          aws: {
            key: process.env.AWS_ACCESS_KEY_ID,
            secret: process.env.AWS_SECRET_ACCESS_KEY
          }
        };
        break;
    }

    // Validate the secret
    secretValue = this.validateSecret(secretType, secretValue);

    this.secrets.set(secretType, {
      value: secretValue,
      timestamp: Date.now(),
      source: 'environment'
    });
  }

  validateSecret(secretType, secretValue) {
    const validators = {
      jwt: (value) => {
        if (!value.access || value.access.length < 32) {
          throw new Error('JWT secret must be at least 32 characters');
        }
        return value;
      },
      database: (value) => {
        if (!value.url) {
          throw new Error('Database URL is required');
        }
        return value;
      },
      api: (value) => {
        if (!value.keys || value.keys.length === 0) {
          console.warn('No API keys configured - all requests will be rejected');
        }
        return value;
      }
    };

    const validator = validators[secretType];
    if (validator) {
      return validator(secretValue);
    }

    return secretValue;
  }

  async validateSecrets() {
    const issues = [];

    // Check for default values in production
    if (process.env.NODE_ENV === 'production') {
      for (const [key, secret] of this.secrets) {
        if (secret.source === 'environment') {
          issues.push(`Secret "${key}" loaded from environment variables in production`);
        }

        // Check for weak secrets
        if (key === 'jwt' && secret.value.access.length < 32) {
          issues.push(`JWT secret is too weak (${secret.value.access.length} chars)`);
        }

        if (key === 'api' && (!secret.value.keys || secret.value.keys.length === 0)) {
          issues.push('No API keys configured');
        }
      }
    }

    if (issues.length > 0) {
      console.warn('⚠️  SECRET VALIDATION ISSUES:');
      issues.forEach(issue => console.warn(`  - ${issue}`));
    }

    return issues;
  }

  getSecret(secretType, key = null) {
    const secret = this.secrets.get(secretType);

    if (!secret) {
      throw new Error(`Secret "${secretType}" not found`);
    }

    // Check cache expiration
    if (Date.now() - secret.timestamp > this.cacheTTL) {
      console.log(`Secret "${secretType}" cache expired, refreshing...`);
      // In a real implementation, you'd refresh here
    }

    if (key) {
      return secret.value[key];
    }

    return secret.value;
  }

  async rotateSecret(secretType) {
    console.log(`Initiating rotation for ${secretType}...`);

    // Clear cache
    this.secrets.delete(secretType);

    // Reload secret
    switch (this.backend) {
      case 'aws':
        await this.loadAWSSecret(secretType);
        break;
      case 'vault':
        await this.loadVaultSecret(`secret/${secretType}`);
        break;
      case 'env':
        await this.loadEnvSecret(secretType);
        break;
    }

    console.log(`Rotation complete for ${secretType}`);
    return this.getSecret(secretType);
  }

  getSecretMetadata() {
    const metadata = {};

    for (const [key, secret] of this.secrets) {
      metadata[key] = {
        source: secret.source || this.backend,
        lastLoaded: new Date(secret.timestamp).toISOString(),
        cacheExpires: new Date(secret.timestamp + this.cacheTTL).toISOString(),
        hasValue: !!secret.value
      };
    }

    return metadata;
  }

  // For testing - generate secure test secrets
  static generateTestSecrets() {
    return {
      jwt: {
        access: crypto.randomBytes(64).toString('hex'),
        refresh: crypto.randomBytes(64).toString('hex'),
        accessExpiry: '15m',
        refreshExpiry: '7d'
      },
      database: {
        url: 'postgres://test:test@localhost:5432/test_db',
        ssl: false
      },
      api: {
        keys: ['test-api-key-' + crypto.randomBytes(16).toString('hex')],
        rateLimit: 1000
      }
    };
  }
}

module.exports = new SecretsManager();

