// auth-middleware.js
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const crypto = require('crypto');
const secretsManager = require('./secrets-manager');

// Secrets will be loaded dynamically from secrets manager
let JWT_ACCESS_SECRET;
let JWT_REFRESH_SECRET;
const ACCESS_TOKEN_EXPIRY = '15m';
const REFRESH_TOKEN_EXPIRY = '7d';

// Initialize secrets (call this during app startup)
const initializeAuthSecrets = async () => {
  try {
    await secretsManager.initialize();
    const jwtSecrets = secretsManager.getSecret('jwt');
    JWT_ACCESS_SECRET = jwtSecrets.access;
    JWT_REFRESH_SECRET = jwtSecrets.refresh || jwtSecrets.access + '-refresh';

    console.log('Auth secrets initialized successfully');
  } catch (error) {
    console.error('Failed to initialize auth secrets:', error);

    // Fallback for development
    if (process.env.NODE_ENV !== 'production') {
      JWT_ACCESS_SECRET = process.env.JWT_ACCESS_SECRET || crypto.randomBytes(64).toString('hex');
      JWT_REFRESH_SECRET = process.env.JWT_REFRESH_SECRET || JWT_ACCESS_SECRET + '-refresh';
      console.warn('⚠️  Using fallback secrets in development mode');
    } else {
      throw new Error('Authentication secrets not available');
    }
  }
};

// API key authentication middleware
const apiKeyAuth = (req, res, next) => {
  const apiKey = req.headers['x-api-key'] || req.query.api_key;

  if (!apiKey) {
    return res.status(401).json({ error: 'API key required' });
  }

  try {
    const apiSecrets = secretsManager.getSecret('api');
    const validApiKeys = apiSecrets.keys || [];

    if (!validApiKeys.includes(apiKey.trim())) {
      console.warn(`Invalid API key attempt from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid API key' });
    }

    req.apiKey = apiKey;
    next();
  } catch (error) {
    console.error('API key validation failed:', error);
    return res.status(500).json({ error: 'Authentication service unavailable' });
  }
};

// JWT authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  if (!JWT_ACCESS_SECRET) {
    console.error('JWT secret not initialized');
    return res.status(500).json({ error: 'Authentication service unavailable' });
  }

  jwt.verify(token, JWT_ACCESS_SECRET, (err, user) => {
    if (err) {
      console.warn(`JWT verification failed: ${err.message} from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid token' });
    }

    req.user = user;
    next();
  });
};

// Role-based authorization middleware
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      console.warn(`Unauthorized role access attempt: ${req.user.role} from ${req.ip}`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// Rate limiting by IP
const rateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});

// Rate limiting by API key
const apiKeyRateLimiter = (maxRequests) => rateLimit({
  windowMs: 15 * 60 * 1000,
  max: maxRequests,
  keyGenerator: (req) => req.apiKey || req.ip,
  message: { error: 'Rate limit exceeded for this API key' },
});

// Function to generate password hash
const hashPassword = async (password) => {
  const saltRounds = 12;
  return await bcrypt.hash(password, saltRounds);
};

// Function to verify password
const verifyPassword = async (password, hash) => {
  return await bcrypt.compare(password, hash);
};

// Generate JWT tokens
const generateTokens = (user) => {
  if (!JWT_ACCESS_SECRET || !JWT_REFRESH_SECRET) {
    throw new Error('JWT secrets not initialized');
  }

  const accessToken = jwt.sign(
    { 
      userId: user.id, 
      email: user.email, 
      role: user.role,
      iss: process.env.APP_NAME || 'express-app',
      aud: 'api-users'
    },
    JWT_ACCESS_SECRET,
    { 
      expiresIn: ACCESS_TOKEN_EXPIRY,
      jwtid: crypto.randomBytes(16).toString('hex') // Unique JWT ID
    }
  );

  const refreshToken = jwt.sign(
    { 
      userId: user.id,
      tokenType: 'refresh'
    },
    JWT_REFRESH_SECRET,
    { 
      expiresIn: REFRESH_TOKEN_EXPIRY,
      jwtid: crypto.randomBytes(16).toString('hex')
    }
  );

  return { accessToken, refreshToken };
};

module.exports = {
  apiKeyAuth,
  authenticateToken,
  authorize,
  rateLimiter,
  apiKeyRateLimiter,
  hashPassword,
  verifyPassword,
  generateTokens,
  initializeAuthSecrets,
  // For testing/debugging only
  _getSecrets: () => ({
    accessSecret: JWT_ACCESS_SECRET ? '***' + JWT_ACCESS_SECRET.slice(-4) : 'not initialized',
    refreshSecret: JWT_REFRESH_SECRET ? '***' + JWT_REFRESH_SECRET.slice(-4) : 'not initialized'
  })
};

