// config/aws-secrets.js
const AWS = require('aws-sdk');
const cache = require('memory-cache');

class AWSSecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cacheDuration = 5 * 60 * 1000; // 5 minutes cache
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = cache.get(secretName);
    if (cached) return cached;

    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the result
      cache.put(secretName, secret, this.cacheDuration);

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  async getDatabaseConfig() {
    const secret = await this.getSecret('prod/database');
    return {
      host: secret.host,
      port: secret.port,
      database: secret.dbname,
      username: secret.username,
      password: secret.password
    };
  }
}

module.exports = new AWSSecretsManager();
