```javascript
// scripts/security-check.js
const fs = require('fs');
const path = require('path');

function checkSecretsSafety() {
  const issues = [];

  // Check for .env files
  const envFiles = fs.readdirSync('.').filter(file => 
    file.startsWith('.env') && !file.includes('.example')
  );

  if (envFiles.length > 0) {
    issues.push(`Found potential secret files: ${envFiles.join(', ')}`);

    // Check if they contain real secrets
    envFiles.forEach(file => {
      const content = fs.readFileSync(file, 'utf8');
      if (!content.includes('CANARY') && !content.includes('example')) {
        issues.push(`${file} may contain real secrets (no canary/example markers)`);
      }
    });
  }

  // Check app.js for hardcoded secrets
  const appContent = fs.readFileSync('app.js', 'utf8');
  const secretPatterns = [
    /password\s*[:=]\s*['"][^'"]+['"]/gi,
    /secret\s*[:=]\s*['"][^'"]+['"]/gi,
    /key\s*[:=]\s*['"][^'"]+['"]/gi,
    /token\s*[:=]\s*['"][^'"]+['"]/gi,
  ];

  secretPatterns.forEach(pattern => {
    if (pattern.test(appContent)) {
      issues.push('Found potential hardcoded secrets in app.js');
    }
  });

  // Check package.json for security tools
  if (fs.existsSync('package.json')) {
    const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
    const securityPackages = ['helmet', 'express-rate-limit', 'joi', 'bcrypt', 'jsonwebtoken'];
    const missing = securityPackages.filter(pkg => 
      !(pkg in (pkg.dependencies || {}))
    );

    if (missing.length > 0) {
      issues.push(`Missing security packages: ${missing.join(', ')}`);
    }
  }

  return issues;
}

const issues = checkSecretsSafety();
if (issues.length > 0) {
  console.error('SECURITY ISSUES FOUND:');
  issues.forEach(issue => console.error(`- ${issue}`));
  process.exit(1);
} else {
  console.log('Security check passed ✓');
}
```

